        search=<strong>{search || "—"}</strong>
        {" · "}status=<strong>{(values.status ?? []).join(",") || "any"}</strong>
        {" · "}owner=<strong>{(values.owner ?? []).join(",") || "any"}</strong>
      </div>
    </>
  );
}

export default function FilterToolbarExample() {
  return <SearchFacetsChips />;
}

