        { keys: ["G", "S"], description: "Go to settings" },
        { keys: ["?"],     description: "Show this shortcut grid" },
        { keys: ["Esc"],   description: "Close any open dialog" },
      ]}
    />
  );
}

export function SingleShortcut() {
