/**
 * SkeletonTable (@patternfly/react-component-groups) — a pre-built skeleton
 * placeholder for tables: same structure as the real Table, with shimmering
 * bars instead of data, so the layout doesn't shift when rows arrive.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import SkeletonTable from "@patternfly/react-component-groups/dist/dynamic/SkeletonTable";

export function Default() {
  return (
    <SkeletonTable
      rowsCount={6}
      columns={["Name", "Status", "Owner", "Last run"]}
    />
  );
}

export function SelectableExpandable() {
  return (
    <SkeletonTable
      rowsCount={4}
      isSelectable
      isExpandable
      columns={["Name", "Status", "Owner", "Last run"]}
    />
  );
}

export default function SkeletonTableExample() {
  return (
    <div style={{ display: "grid", gap: 24 }}>
      <Default />
      <SelectableExpandable />
    </div>
  );
}

/**
 * StaleDataWarning (@patternfly/react-component-groups) — a tooltip-icon for
 * objects nearing or past a freshness threshold (old check-in data,
 * abandoned workflows, unupdated host inventory).
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import StaleDataWarning from "@patternfly/react-component-groups/dist/dynamic/StaleDataWarning";

const now = new Date("2026-05-10T09:00:00Z");
const staleWarning = new Date("2026-05-09T00:00:00Z"); // 1 day before warning
const stale         = new Date("2026-05-08T00:00:00Z"); // marked stale 2 days ago
const culled        = new Date("2026-05-15T00:00:00Z"); // will be deleted in 5 days

export function Default() {
  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        gap: 8,
        color: "var(--gp-color-text-regular)",
      }}
    >
      <span><strong>worker-23</strong></span>
      <StaleDataWarning
        stale={stale}
        staleWarning={staleWarning}
        culled={culled}
        currDate={now}
      />
      <span style={{ color: "var(--gp-color-text-subtle)" }}>
        · last check-in 2 days ago
      </span>
    </div>
  );
}

export default function StaleDataWarningExample() {
  return <Default />;
}

/**
 * Status (@patternfly/react-component-groups) — a standardized icon + label
 * pair for object state (Healthy / Degraded / Failed / Unknown), with
 * popover and link variants for explanatory detail.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { Status } from "@patternfly/react-component-groups/dist/dynamic/Status";

export function Plain() {
  return (
    <div style={{ display: "grid", gap: 8 }}>
      <Status status="success" label="Healthy" />
      <Status status="info"    label="Provisioning" />
      <Status status="warning" label="Degraded" />
      <Status status="danger"  label="Failed" />
