}

export default function StatusExample() {
  return (
    <div style={{ display: "grid", gap: 24 }}>
      <Plain />
      <PopoverVariant />
      <IconOnly />
    </div>
  );
}

/**
 * TagCount (@patternfly/react-component-groups) — a small clickable tag
 * indicator with a count ("3 tags") for table rows where rendering all tags
