/**
 * DatePicker — the lib's DateField lego block: a text input + a popover
 * calendar (three-view days → months → years, with a mobile bottom-sheet),
 * controlled by a `Date | null`. Everything below is just configuration —
 * the calendar engine lives in the exported component.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { useState } from "react";
import { DateField, FormGroup, HelperText, HelperTextItem } from "@golden-passport/ds-patternfly";

export function Default() {
  const [date, setDate] = useState<Date | null>(null);
  return (
    <FormGroup label="Due date" isRequired>
      <DateField value={date} onChange={setDate} ariaLabel="Due date" />
    </FormGroup>
  );
}

export function Flat() {
  const [date, setDate] = useState<Date | null>(null);
  return <DateField display="flat" value={date} onChange={setDate} ariaLabel="Pick a date" />;
}

export function Modal() {
  const [date, setDate] = useState<Date | null>(null);
  return (
    <FormGroup label="Start date">
      <DateField
        display="modal"
        value={date}
        onChange={setDate}
        ariaLabel="Start date"
        modalTitle="Pick a start date"
      />
    </FormGroup>
  );
}

export function MinMax() {
  const today = new Date();
  const in30 = new Date();
  in30.setDate(in30.getDate() + 30);
  const [date, setDate] = useState<Date | null>(null);
  return (
    <FormGroup label="Booking — today through 30 days out" isRequired>
      <DateField
        value={date}
        onChange={setDate}
        ariaLabel="Booking date"
        minDate={today}
        maxDate={in30}
      />
    </FormGroup>
  );
}

export function ExcludedDates() {
  const [date, setDate] = useState<Date | null>(null);
  // A consumer-supplied predicate — return false to disable a day. Here, a set
  // of public holidays. The component greys these out in every view.
  const holidays = new Set([
    "2026-01-01",
    "2026-04-03",
    "2026-12-25",
    "2026-12-26",
  ]);
  return (
    <FormGroup label="Available booking dates" isRequired>
      <DateField
        value={date}
        onChange={setDate}
        ariaLabel="Booking date (holidays excluded)"
        validators={[
          (d) => {
            const iso = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
            return !holidays.has(iso);
          },
        ]}
      />
    </FormGroup>
  );
}

export function DateRange() {
  const [start, setStart] = useState<Date | null>(null);
  const [end, setEnd] = useState<Date | null>(null);
  return (
    <FormGroup label="Trip dates" isRequired>
      <div style={{ display: "flex", gap: 12, alignItems: "center", flexWrap: "wrap" }}>
        <DateField value={start} onChange={setStart} ariaLabel="Trip start date" placeholder="From" />
        <span style={{ color: "var(--gp-color-text-subtle)" }}>to</span>
        <DateField
          value={end}
          onChange={setEnd}
          ariaLabel="Trip end date"
          placeholder="To"
          {...(start ? { minDate: start, rangeStart: start } : {})}
        />
      </div>
    </FormGroup>
  );
}

export function I18n() {
  const [date, setDate] = useState<Date | null>(null);
  return (
    <FormGroup label="Date — French month names">
      <DateField value={date} onChange={setDate} ariaLabel="Date (français)" locale="fr-FR" />
    </FormGroup>
  );
}

export function WithValidation() {
  const today = new Date();
  const [date, setDate] = useState<Date | null>(null);
  return (
    <FormGroup label="Future date only">
      <DateField value={date} onChange={setDate} ariaLabel="Future date" minDate={today} />
      <HelperText>
        <HelperTextItem>
          Past dates are disabled in the calendar and rejected on the input.
        </HelperTextItem>
      </HelperText>
    </FormGroup>
  );
}

export default function DatePickerExample() {
  return (
    <div style={{ display: "grid", gap: 24 }}>
      <Default />
      <Flat />
      <Modal />
      <MinMax />
      <ExcludedDates />
      <DateRange />
      <I18n />
      <WithValidation />
    </div>
  );
}

/**
 * DateTimePicker — a date + a time under one FormGroup, composed from the
 * exported DateField (the calendar engine) and TimeField. The consumer owns
 * the two values; each control owns its own UI.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { useId, useState } from "react";
import { DateField, FormGroup, TimeField } from "@golden-passport/ds-patternfly";

export function SideBySide() {
  const id = useId();
  const [date, setDate] = useState<Date | null>(null);
  const [time, setTime] = useState("");

  return (
    <FormGroup label="Schedule for" isRequired fieldId={id}>
      <div style={{ display: "flex", gap: 12, flexWrap: "wrap" }}>
        <DateField value={date} onChange={setDate} ariaLabel="Schedule date" />
        <TimeField
          value={time}
          onChange={setTime}
          ariaLabel="Schedule time"
          is24Hour
          stepMinutes={15}
        />
      </div>
    </FormGroup>
  );
}

export default function DateTimePickerExample() {
  return <SideBySide />;
}

/**
 * DurationPicker — "run again after" scheduling with the exported DateField.
 * `allowRelative` + `relativeMode="duration"` add a Wait tab whose days/hours/
 * minutes steppers emit an ISO-8601 duration (e.g. "PT2H30M") via
 * `onDurationChange`, while the Specific date tab emits an absolute Date via
 * `onChange`. So the result is a discriminated union — a duration OR a date.
 * Set `relativeOnly` to drop the calendar and offer the duration alone.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { useState } from "react";
import { DateField, FormGroup } from "@golden-passport/ds-patternfly";

// The picker can yield either kind of value — type both.
type RunAgainAfter =
  | { kind: "duration"; duration: string }
  | { kind: "date"; date: Date };

const HELP =
  "Fire this task after a relative wait, or on a specific date.";

const resultBox = {
  margin: 0,
  padding: 12,
  background: "var(--gp-color-bg-secondary-default)",
  borderRadius: 6,
  fontSize: 13,
  color: "var(--gp-color-text-regular)",
} as const;

function describe(r: RunAgainAfter | null): string {
  if (!r) return "// nothing picked yet";
  return r.kind === "duration"
    ? `duration → ${r.duration}`
    : `date → ${r.date.toDateString()}`;
}

export function DurationOrDate() {
  const [result, setResult] = useState<RunAgainAfter | null>(null);
  return (
    <FormGroup label="Run again after" fieldId="run-after">
      <div style={{ display: "grid", gap: 16 }}>
        <DateField
          value={result?.kind === "date" ? result.date : null}
          // Show the chosen duration in the field when no date is set.
          {...(result?.kind === "duration" ? { durationValue: result.duration } : {})}
          // Specific date tab → a Date.
          onChange={(date) => setResult(date ? { kind: "date", date } : null)}
          // Wait tab → an ISO-8601 duration string.
          onDurationChange={(duration) => setResult({ kind: "duration", duration })}
          ariaLabel="Run again after"
          modalTitle="Schedule"
          allowRelative
          relativeMode="duration"
          relativeTabLabel="Wait"
          relativeHelpText={HELP}
        />
        <pre style={resultBox} aria-live="polite">
          {describe(result)}
        </pre>
      </div>
    </FormGroup>
  );
}

export function DurationOnly() {
  const [duration, setDuration] = useState("PT0S");
  // relativeOnly drops the calendar — a pure duration picker.
  return (
    <FormGroup label="Retry delay" fieldId="retry-delay">
      <div style={{ display: "grid", gap: 16 }}>
        <DateField
          value={null}
          {...(duration !== "PT0S" ? { durationValue: duration } : {})}
          onChange={() => {}}
          ariaLabel="Retry delay"
          modalTitle="Retry delay"
          allowRelative
          relativeOnly
          relativeMode="duration"
          relativeTabLabel="Wait"
          onDurationChange={setDuration}
        />
        <pre style={resultBox} aria-live="polite">
          {duration}
        </pre>
      </div>
    </FormGroup>
  );
}

export default function DurationPickerExample() {
  return (
    <div style={{ display: "grid", gap: 24 }}>
      <DurationOrDate />
      <DurationOnly />
    </div>
  );
}

/**
 * FuturePicker — the exported DateField restricted to future dates with
 * `futureOnly` (today and earlier are disabled). Same calendar engine and
 * controlled `Date | null` API as DateField — just a future-only floor. For
 * scheduling, expiries, and "remind me on…" pickers.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { useState } from "react";
import { DateField, FormGroup } from "@golden-passport/ds-patternfly";

export function LiveDemo() {
  const [date, setDate] = useState<Date | null>(null);
  return (
    <FormGroup label="Remind me on" fieldId="future-remind">
      <DateField value={date} onChange={setDate} ariaLabel="Reminder date" futureOnly />
    </FormGroup>
  );
}

export function ModalVersion() {
  const [date, setDate] = useState<Date | null>(null);
  return (
    <FormGroup label="Expires on" fieldId="future-expires">
      <DateField
        display="modal"
        value={date}
        onChange={setDate}
        ariaLabel="Expiry date"
        modalTitle="Pick an expiry date"
        futureOnly
      />
    </FormGroup>
  );
}

export default function FuturePickerExample() {
  return (
    <div style={{ display: "grid", gap: 24 }}>
      <LiveDemo />
      <ModalVersion />
    </div>
  );
}

