      <Switch id={`${id}-disabled-off`} label="Disabled (off)" isChecked={false} onChange={() => {}} isDisabled />
      <Switch id={`${id}-disabled-on`} label="Disabled (on)" isChecked onChange={() => {}} isDisabled />
    </div>
  );
}

export default function SwitchExample() {
  return <States />;
}

