        {COLORS.map((c) => (
          <Label key={c} variant="outline" color={c}>
            {c}
          </Label>
        ))}
      </div>
    </div>
  );
}

export function CompactLabels() {
  return (
    <div
      style={{
        display: "flex",
        gap: 8,
        flexWrap: "wrap",
        alignItems: "center",
      }}
    >
      <Label isCompact status="info">Info</Label>
