/**
 * Wizard — a multi-step task runner with a step rail, per-step body, and a
 * standard footer (Back / Next / Cancel / Submit).
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { useId, useState } from "react";
import {
  Button,
  Checkbox,
  Form,
  FormGroup,
  Modal,
  ModalVariant,
  Radio,
  TextArea,
  TextInput,
  Wizard,
  WizardStep,
  type WizardStepType,
} from "@golden-passport/ds-patternfly";

// Field / step ids derive from useId() so several wizards can coexist on
// one page without duplicate-id clashes.

export function InlineWizard() {
  const id = useId();
  const [name, setName] = useState("");
  const [region, setRegion] = useState("us-east-1");
  const [size, setSize] = useState("medium");
  const [autoBackup, setAutoBackup] = useState(true);
  const [notes, setNotes] = useState("");
  const [completed, setCompleted] = useState<string | null>(null);

  const reset = () => {
    setName("");
    setRegion("us-east-1");
    setSize("medium");
    setAutoBackup(true);
    setNotes("");
  };

  return (
    <div style={{ display: "grid", gap: 16 }}>
      <Wizard
        navAriaLabel="Create deployment steps"
        height={420}
        onSave={() => setCompleted(name || "(unnamed)")}
        onClose={() => {
          reset();
          setCompleted(null);
        }}
      >
        <WizardStep id={`${id}-step-name`} name="Name">
          <Form>
            <FormGroup label="Deployment name" isRequired fieldId={`${id}-name`}>
              <TextInput
                id={`${id}-name`}
                value={name}
                onChange={(_e, v) => setName(v)}
                isRequired
              />
            </FormGroup>
          </Form>
        </WizardStep>
        <WizardStep id={`${id}-step-region`} name="Region">
          <Form>
            <FormGroup label="Region" fieldId={`${id}-region`} isStack>
              {["us-east-1", "us-west-2", "eu-central-1"].map((r) => (
                <Radio
                  key={r}
                  id={`${id}-region-${r}`}
                  name={`${id}-region`}
                  label={r}
                  isChecked={region === r}
                  onChange={() => setRegion(r)}
                />
              ))}
            </FormGroup>
          </Form>
        </WizardStep>
        <WizardStep id={`${id}-step-size`} name="Size">
          <Form>
            <FormGroup label="Instance size" fieldId={`${id}-size`} isStack>
              {["small", "medium", "large"].map((s) => (
                <Radio
                  key={s}
                  id={`${id}-size-${s}`}
                  name={`${id}-size`}
                  label={s}
                  isChecked={size === s}
                  onChange={() => setSize(s)}
                />
              ))}
            </FormGroup>
            <FormGroup fieldId={`${id}-backup`}>
              <Checkbox
                id={`${id}-backup`}
                label="Enable automatic backups"
                isChecked={autoBackup}
                onChange={(_e, c) => setAutoBackup(c)}
              />
            </FormGroup>
          </Form>
        </WizardStep>
        <WizardStep id={`${id}-step-review`} name="Review" footer={{ nextButtonText: "Create deployment" }}>
          <Form>
            <FormGroup label="Summary" fieldId={`${id}-summary`}>
              <ul style={{ margin: 0, paddingLeft: 18, lineHeight: 1.8 }}>
                <li>Name: <strong>{name || "—"}</strong></li>
                <li>Region: <strong>{region}</strong></li>
                <li>Size: <strong>{size}</strong></li>
                <li>Backups: <strong>{autoBackup ? "enabled" : "disabled"}</strong></li>
              </ul>
            </FormGroup>
            <FormGroup label="Notes (optional)" fieldId={`${id}-notes`}>
              <TextArea
                id={`${id}-notes`}
                value={notes}
                onChange={(_e, v) => setNotes(v)}
                rows={3}
              />
            </FormGroup>
          </Form>
        </WizardStep>
      </Wizard>
      {completed !== null && (
        <p style={{ margin: 0, color: "var(--gp-color-text-subtle)" }}>
          ✓ Created <strong>{completed}</strong>. (Press Cancel to reset the
          demo.)
        </p>
      )}
    </div>
  );
}

export function InModal() {
  const id = useId();
  const [modalOpen, setModalOpen] = useState(false);

  return (
    <>
      <Button onClick={() => setModalOpen(true)}>
        Launch wizard in modal
      </Button>
      <Modal
        variant={ModalVariant.large}
        isOpen={modalOpen}
        onClose={() => setModalOpen(false)}
        aria-label="Create deployment wizard"
      >
        <Wizard
          navAriaLabel="Create deployment steps"
          height={420}
          onSave={() => setModalOpen(false)}
          onClose={() => setModalOpen(false)}
        >
          <WizardStep id={`${id}-m-step-1`} name="Name">
            <Form>
              <FormGroup label="Deployment name" fieldId={`${id}-m-name`}>
                <TextInput id={`${id}-m-name`} />
              </FormGroup>
            </Form>
          </WizardStep>
          <WizardStep id={`${id}-m-step-2`} name="Configure">
            <p>Pick options for your deployment.</p>
          </WizardStep>
          <WizardStep
            id={`${id}-m-step-3`}
            name="Review"
            footer={{ nextButtonText: "Create" }}
          >
            <p>Confirm and submit.</p>
          </WizardStep>
        </Wizard>
      </Modal>
    </>
  );
}

export function Progressive() {
  const id = useId();

  return (
    <Wizard navAriaLabel="Progressive steps" isProgressive height={280}>
      <WizardStep id={`${id}-p-1`} name="Choose source">
        <p>Select where to deploy from.</p>
      </WizardStep>
      <WizardStep id={`${id}-p-2`} name="Pick branch">
        <p>Branch list depends on source.</p>
      </WizardStep>
      <WizardStep id={`${id}-p-3`} name="Confirm">
        <p>Final confirmation step.</p>
      </WizardStep>
    </Wizard>
  );
}

export function VisitRequired() {
  const id = useId();

  return (
    <Wizard
      navAriaLabel="Visit-required steps"
      isVisitRequired
      height={280}
      onStepChange={(_e, current: WizardStepType) => void current}
    >
      <WizardStep id={`${id}-v-1`} name="Step one">
        <p>Visit each step in order.</p>
      </WizardStep>
      <WizardStep id={`${id}-v-2`} name="Step two">
        <p>Now reachable.</p>
      </WizardStep>
      <WizardStep id={`${id}-v-3`} name="Step three">
        <p>Reachable after step two is visited.</p>
      </WizardStep>
    </Wizard>
  );
}

export default function WizardExample() {
  return (
    <div style={{ display: "grid", gap: 24 }}>
      <InlineWizard />
      <InModal />
      <Progressive />
      <VisitRequired />
    </div>
  );
}

/**
 * CatalogItemHeader (@patternfly/react-catalog-view-extension) — the page
 * header for a single catalog item: large icon, title, vendor line.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { CatalogItemHeader } from "@patternfly/react-catalog-view-extension";
import { CubeIcon } from "@patternfly/react-icons";
import "@patternfly/react-catalog-view-extension/dist/css/react-catalog-view-extension.css";

export function Default() {
  return (
    <CatalogItemHeader
      title="Workflow engine"
      vendor="Provided by Acme"
      iconClass="fas fa-cube"
    />
  );
}

export function CustomNodes() {
  return (
    <CatalogItemHeader
      title={
        <span style={{ display: "inline-flex", alignItems: "center", gap: 8 }}>
          <CubeIcon /> Workflow engine
        </span>
      }
      vendor={<a href="#vendor">Acme &rsaquo;</a>}
    />
  );
}

export default function CatalogItemHeaderExample() {
  return (
    <div style={{ display: "grid", gap: 24 }}>
      <Default />
      <CustomNodes />
    </div>
  );
}

/**
 * CatalogTile (@patternfly/react-catalog-view-extension) — a single tile in
 * a catalog grid: title, vendor, description, optional icon, badges, footer.
 * Renders as a link with `href`, or as a selectable card with
 * `isSelected` + `onClick`.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { useId, useState } from "react";
import {
  CatalogTile,
  CatalogTileBadge,
} from "@patternfly/react-catalog-view-extension";
import { CubeIcon, LockIcon, StarIcon } from "@patternfly/react-icons";
import "@patternfly/react-catalog-view-extension/dist/css/react-catalog-view-extension.css";
import { Gallery, GalleryItem, Button } from "@golden-passport/ds-patternfly";

export function FeaturedAndStandard() {
  const id = useId();
  return (
    <Gallery hasGutter minWidths={{ default: "260px" }}>
      <GalleryItem>
        <CatalogTile
          id={`${id}-workflow-engine`}
          featured
          href="#/featured"
          icon={<CubeIcon style={{ fontSize: 28 }} />}
          title="Workflow engine"
          vendor="Provided by Acme"
          description="The headline product — sits front and centre on the catalog landing page."
          badges={[
            <CatalogTileBadge key="star" title="Featured">
              <StarIcon />
            </CatalogTileBadge>,
          ]}
        />
      </GalleryItem>
      <GalleryItem>
        <CatalogTile
          id={`${id}-log-delivery`}
          featured={false}
          href="#/standard"
          icon={<CubeIcon style={{ fontSize: 28 }} />}
          title="Log delivery"
          vendor="Provided by Acme"
          description="A standard tile — equal visual weight as its siblings."
        />
      </GalleryItem>
    </Gallery>
  );
}

export function Selectable() {
  const id = useId();
  const [selected, setSelected] = useState<string | null>(null);
  return (
    <>
      <Gallery hasGutter minWidths={{ default: "240px" }}>
        {["small", "medium", "large"].map((size) => (
          <GalleryItem key={size}>
            <CatalogTile
              id={`${id}-size-${size}`}
              featured={false}
              href=""
              title={size}
              vendor="Instance size"
              description={`Pick the ${size} option to right-size your deployment.`}
              isSelected={selected === size}
              onClick={() => setSelected(size)}
            />
          </GalleryItem>
        ))}
      </Gallery>
      <p style={{ marginTop: 8, color: "var(--gp-color-text-subtle)" }}>
        Selected: <strong>{selected ?? "—"}</strong>
      </p>
    </>
  );
}

export function WithFooter() {
  const id = useId();
  return (
    <Gallery hasGutter minWidths={{ default: "260px" }}>
      <GalleryItem>
        <CatalogTile
          id={`${id}-ci-runner`}
          featured={false}
          href=""
          title="CI runner"
          vendor="Beta Co"
          description="Auto-scaling build agents with caching."
          badges={[
            <CatalogTileBadge key="lock" title="License required">
              <LockIcon />
            </CatalogTileBadge>,
          ]}
          footer={<Button variant="primary">Install</Button>}
        />
      </GalleryItem>
    </Gallery>
  );
}

export default function CatalogTileExample() {
  return (
    <div style={{ display: "grid", gap: 24 }}>
      <FeaturedAndStandard />
      <Selectable />
      <WithFooter />
    </div>
  );
}

/**
 * Catalog view (@patternfly/react-catalog-view-extension) — a grid of
 * selectable / linkable CatalogTile cards for catalogs: services, plugins,
 * marketplace items.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { useId } from "react";
import {
  CatalogTile,
  CatalogTileBadge,
} from "@patternfly/react-catalog-view-extension";
import { StarIcon, CubeIcon } from "@patternfly/react-icons";
import "@patternfly/react-catalog-view-extension/dist/css/react-catalog-view-extension.css";
import { Gallery, GalleryItem } from "@golden-passport/ds-patternfly";

const items = [
  { id: "wf",     title: "Workflow engine",    vendor: "Acme",    desc: "Trigger and orchestrate jobs across services.", featured: true },
  { id: "ld",     title: "Log delivery",       vendor: "Acme",    desc: "Stream logs from any source to your data lake." },
  { id: "ci",     title: "CI runner",          vendor: "Beta Co", desc: "Auto-scaling build agents with caching." },
  { id: "mon",    title: "Monitoring stack",   vendor: "Gamma",   desc: "Prometheus + Grafana, batteries included." },
  { id: "sec",    title: "Secrets manager",    vendor: "Acme",    desc: "Rotating credentials with audit log." },
  { id: "alerts", title: "Incident alerts",    vendor: "Delta",   desc: "Route incidents to the right on-call." },
];

export function TileGrid() {
  const id = useId();
  return (
    <Gallery hasGutter minWidths={{ default: "260px" }}>
      {items.map((it) => (
        <GalleryItem key={it.id}>
          <CatalogTile
            id={`${id}-${it.id}`}
            featured={!!it.featured}
            href={`#/${it.id}`}
            icon={<CubeIcon style={{ fontSize: 28 }} />}
            title={it.title}
            vendor={`Provided by ${it.vendor}`}
            description={it.desc}
            badges={
              it.featured
                ? [
                    <CatalogTileBadge key="star" title="Featured">
                      <StarIcon />
                    </CatalogTileBadge>,
                  ]
                : []
            }
          />
        </GalleryItem>
      ))}
    </Gallery>
  );
}

export default function CatalogViewExample() {
  return <TileGrid />;
}

/**
 * FilterSidePanel (@patternfly/react-catalog-view-extension) — the left rail
 * of facet checkboxes for a catalog page: vendor, type, status, region.
 * Pair FilterSidePanel with one or more FilterSidePanelCategory blocks;
 * each category has a Show-X-more affordance baked in.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { useState } from "react";
import {
  FilterSidePanel,
  FilterSidePanelCategory,
  FilterSidePanelCategoryItem,
} from "@patternfly/react-catalog-view-extension";
import "@patternfly/react-catalog-view-extension/dist/css/react-catalog-view-extension.css";

export function TwoCategories() {
  const [vendors, setVendors] = useState<Set<string>>(new Set(["acme"]));
  const [types, setTypes] = useState<Set<string>>(new Set());
  const toggle = (set: Set<string>, key: string, setter: (s: Set<string>) => void) => {
    const next = new Set(set);
    if (next.has(key)) next.delete(key);
    else next.add(key);
    setter(next);
  };

  return (
    <div style={{ maxWidth: 240 }}>
      <FilterSidePanel>
        <FilterSidePanelCategory title="Vendor">
          {[
            { key: "acme",  label: "Acme",     count: 42 },
            { key: "beta",  label: "Beta Co",  count: 17 },
            { key: "gamma", label: "Gamma",    count: 8 },
            { key: "delta", label: "Delta",    count: 3 },
          ].map((v) => (
            <FilterSidePanelCategoryItem
              key={v.key}
              checked={vendors.has(v.key)}
              onClick={() => toggle(vendors, v.key, setVendors)}
              count={v.count}
            >
              {v.label}
            </FilterSidePanelCategoryItem>
          ))}
        </FilterSidePanelCategory>
        <FilterSidePanelCategory
          title="Type"
          maxShowCount={3}
          leeway={1}
        >
          {[
            { key: "service",  label: "Service",  count: 24 },
            { key: "operator", label: "Operator", count: 11 },
            { key: "broker",   label: "Broker",   count: 7 },
            { key: "plugin",   label: "Plugin",   count: 5 },
            { key: "package",  label: "Package",  count: 2 },
          ].map((t) => (
            <FilterSidePanelCategoryItem
              key={t.key}
              checked={types.has(t.key)}
              onClick={() => toggle(types, t.key, setTypes)}
              count={t.count}
            >
              {t.label}
            </FilterSidePanelCategoryItem>
          ))}
        </FilterSidePanelCategory>
      </FilterSidePanel>
    </div>
  );
}

export default function FilterSidePanelExample() {
  return <TwoCategories />;
}

/**
 * PropertiesSidePanel (@patternfly/react-catalog-view-extension) — the right
 * rail of metadata on a catalog detail page: version, maintainer, support
 * level, expires-on. Pair PropertiesSidePanel with one or more PropertyItem
 * children, and stack actions (Install, Subscribe) at the bottom.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import {
  PropertiesSidePanel,
  PropertyItem,
} from "@patternfly/react-catalog-view-extension";
import "@patternfly/react-catalog-view-extension/dist/css/react-catalog-view-extension.css";
import { Button } from "@golden-passport/ds-patternfly";

export function StandardLayout() {
  return (
    <div style={{ maxWidth: 280 }}>
      <PropertiesSidePanel>
        <PropertyItem label="Version"        value="6.4.0" />
        <PropertyItem label="Maintainer"     value="Acme" />
        <PropertyItem label="Support level"  value="Community" />
        <PropertyItem label="Last updated"   value="2026-04-29" />
        <PropertyItem
          label="Documentation"
          value={<a href="#docs">Read the docs ›</a>}
        />
        {/* Give the action room to breathe — separate it from the property
            list above and keep it off the panel's bottom edge. */}
        <div style={{ marginBlockStart: "1.5rem", marginBlockEnd: "0.5rem" }}>
          <Button variant="primary" isBlock>
            Install
          </Button>
        </div>
      </PropertiesSidePanel>
    </div>
  );
}

export default function PropertiesSidePanelExample() {
  return <StandardLayout />;
}

/**
 * VerticalTabs (@patternfly/react-catalog-view-extension) — a left-rail tab
 * list, common as the secondary nav inside a catalog item detail page
 * (Overview / Configuration / Permissions / Logs). Less heavyweight than
 * PageSidebar, cleaner than horizontal Tabs when you have ≥ 4 entries.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { useState } from "react";
import {
  VerticalTabs,
  VerticalTabsTab,
} from "@patternfly/react-catalog-view-extension";
import "@patternfly/react-catalog-view-extension/dist/css/react-catalog-view-extension.css";

const tabs = ["Overview", "Configuration", "Permissions", "Logs", "Activity"];

export function Default() {
  const [active, setActive] = useState("Overview");
  return (
    <div style={{ display: "flex", gap: 24 }}>
      <div style={{ minWidth: 180 }}>
        <VerticalTabs>
          {tabs.map((t) => (
            <VerticalTabsTab
              key={t}
              title={t}
              href={`#${t.toLowerCase()}`}
              active={active === t}
              onActivate={() => setActive(t)}
            />
          ))}
        </VerticalTabs>
      </div>
      <div style={{ flex: 1, color: "var(--gp-color-text-regular)" }}>
        <strong>{active}</strong>
        <p style={{ marginTop: 8, color: "var(--gp-color-text-subtle)" }}>
          Render the active tab&rsquo;s panel here.
        </p>
      </div>
    </div>
  );
}

export function Nested() {
  return (
    <div style={{ minWidth: 200 }}>
      {/* The extension renders each VerticalTabsTab as <li>;
          nested VerticalTabsTab children must be wrapped in a
          sub-VerticalTabs (<ul>) so the markup stays valid
          (<li> can't appear directly inside <li>). */}
      <VerticalTabs restrictTabs activeTab>
        <VerticalTabsTab title="Overview" active />
        <VerticalTabsTab title="Configuration" hasActiveDescendant>
          <VerticalTabs>
            <VerticalTabsTab title="General" active />
            <VerticalTabsTab title="Networking" />
            <VerticalTabsTab title="Storage" />
          </VerticalTabs>
        </VerticalTabsTab>
        <VerticalTabsTab title="Permissions" />
      </VerticalTabs>
    </div>
  );
}

export default function VerticalTabsExample() {
  return (
    <div style={{ display: "grid", gap: 24 }}>
      <Default />
      <Nested />
    </div>
  );
}

/**
 * DataView (@patternfly/react-data-view) — a pre-wired Table + Toolbar +
 * Pagination + Selection package. The hooks (useDataViewSelection,
 * useDataViewPagination, useDataViewSort) own the state and produce the
 * props each piece expects.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { useId } from "react";
import {
  DataView,
  DataViewTable,
  DataViewToolbar,
  useDataViewPagination,
  useDataViewSelection,
} from "@patternfly/react-data-view";
import { Pagination } from "@golden-passport/ds-patternfly";

type Workflow = { id: string; name: string; status: string; owner: string };

const ALL: Workflow[] = Array.from({ length: 23 }).map((_, i) => ({
  id: `wf-${i + 1}`,
  name: `Workflow ${i + 1}`,
  status: ["Active", "Paused", "Failed"][i % 3] ?? "Active",
  owner: ["ada", "grace", "linus"][i % 3] ?? "ada",
}));

export function ComposedDataView() {
  const id = useId();
  const pagination = useDataViewPagination({ perPage: 5 });
  const selection = useDataViewSelection({
    matchOption: (a: Workflow, b: Workflow) => a.id === b.id,
  });

  const start = (pagination.page - 1) * pagination.perPage;
  const pageRows = ALL.slice(start, start + pagination.perPage);

  const columns = ["Name", "Status", "Owner"];
  const rows = pageRows.map((r) => ({
    id: r.id,
    row: [r.name, r.status, r.owner],
  }));

  return (
    <DataView selection={selection}>
      <DataViewToolbar
        pagination={
          <Pagination
            itemCount={ALL.length}
            page={pagination.page}
            perPage={pagination.perPage}
            onSetPage={pagination.onSetPage}
            onPerPageSelect={pagination.onPerPageSelect}
            widgetId={`${id}-pagination`}
            isCompact
          />
        }
      />
      <DataViewTable
        aria-label="Workflows data view"
        columns={columns}
        rows={rows}
      />
    </DataView>
  );
}

export default function DataViewOverviewExample() {
  return <ComposedDataView />;
}

