/**
 * DataViewToolbar (@patternfly/react-data-view) — the toolbar that sits
 * above a Data view table. Named slots for filters, bulk select, actions,
 * view-toggle group, and pagination — everything is a render-slot, so you
 * stay in control of the inner components.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { useId, useState } from "react";
import {
  DataView,
  DataViewToolbar,
  DataViewTextFilter,
  useDataViewPagination,
} from "@patternfly/react-data-view";
import { Button, Pagination } from "@golden-passport/ds-patternfly";

export function FiltersActionsPagination() {
  const id = useId();
  const [search, setSearch] = useState("");
  const pagination = useDataViewPagination({ perPage: 20 });
  return (
    <DataView>
      <DataViewToolbar
        filters={
          <DataViewTextFilter
            filterId="name"
            title="Name"
            value={search}
            onChange={(_e, v) => setSearch(v as string)}
            placeholder="Filter by name"
          />
        }
        actions={<Button variant="primary">Create workflow</Button>}
        pagination={
          <Pagination
            itemCount={142}
            page={pagination.page}
            perPage={pagination.perPage}
            onSetPage={pagination.onSetPage}
            onPerPageSelect={pagination.onPerPageSelect}
            widgetId={`${id}-pagination`}
            isCompact
          />
        }
      />
    </DataView>
  );
}

export default function DataViewToolbarExample() {
  return <FiltersActionsPagination />;
}

/**
 * LogViewer (@patternfly/react-log-viewer) — a virtualised log-streaming
 * component with ANSI colour support, search, line numbers, and dark/light
 * themes. Use it whenever you need to render > a few hundred lines of
 * machine output without freezing the page.
 *
 * NOTE: LogViewer mounts an off-screen measurement layer at construction
 * time that breaks under headless-browser test runners — verify the live
 * component in a real browser.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { LogViewer, LogViewerSearch } from "@patternfly/react-log-viewer";
import { Toolbar, ToolbarContent, ToolbarItem } from "@golden-passport/ds-patternfly";

const logText = `2026-05-10T09:21:14.231Z [ERROR] worker-3  ConnectionResetError: connection closed by upstream
2026-05-10T09:21:15.402Z [WARN ] worker-1  step 2 took 14.2s (threshold: 10s)
2026-05-10T09:21:16.118Z [INFO ] worker-0  processed event #1029
2026-05-10T09:21:16.875Z [INFO ] worker-2  processed event #1030`;

export function Default() {
  return (
    <LogViewer
      data={logText}
      hasLineNumbers
      height={400}
      theme="dark"
    />
  );
}

export function WithSearchToolbar() {
  return (
    <LogViewer
      data={logText}
      hasLineNumbers
      height={400}
      theme="dark"
      toolbar={
        <Toolbar>
          <ToolbarContent>
            <ToolbarItem>
              <LogViewerSearch placeholder="Search logs" minSearchChars={1} />
            </ToolbarItem>
          </ToolbarContent>
        </Toolbar>
      }
    />
  );
}

export default function LogViewerExample() {
  return (
    <div style={{ display: "grid", gap: 24 }}>
      <Default />
      <WithSearchToolbar />
    </div>
  );
}

/**
 * Quick starts (@patternfly/quickstarts) — guided product tours rendered
 * from declarative YAML / JSON. QuickStartContainer wraps your app's
 * routes and manages the active tour, completed steps, and the drawer
 * that holds the step UI; QuickStartCatalogPage renders the catalog grid.
 *
 * Quick starts wraps the entire app shell in a Drawer + Context provider —
 * these are code-only recipes; preview them in a real app shell.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { useState, type ReactNode } from "react";
import {
  QuickStartContainer,
  QuickStartCatalogPage,
  type AllQuickStartStates,
  type QuickStart,
} from "@patternfly/quickstarts";
import "@patternfly/quickstarts/dist/quickstarts.css";

// quickstarts-data.ts — each quick start is a JSON / YAML object with
// metadata + an array of tasks.
export const quickStarts: QuickStart[] = [
  {
    apiVersion: "console.openshift.io/v1",
    kind: "QuickStarts",
    metadata: { name: "create-workflow" },
