  DropdownList,
  MenuToggle,
  type MenuToggleElement,
} from "@golden-passport/ds-patternfly";
import { EllipsisVIcon } from "@patternfly/react-icons";

export function PrimaryAndSecondary() {
  return (
    <div style={{ display: "flex", gap: 8 }}>
      <Button variant="primary">Save</Button>
      <Button variant="secondary">Save as draft</Button>
      <Button variant="link">Cancel</Button>
    </div>
  );
}

export function DestructiveAction() {
  return (
    <div style={{ display: "flex", gap: 8 }}>
      <Button variant="danger">Delete</Button>
      <Button variant="secondary">Cancel</Button>
    </div>
  );
}

export function PrimaryAndOverflow() {
  const [open, setOpen] = useState(false);

  return (
    <div style={{ display: "flex", gap: 8 }}>
      <Button variant="primary">Run</Button>
      <Dropdown
        isOpen={open}
        onSelect={() => setOpen(false)}
        onOpenChange={setOpen}
        toggle={(toggleRef: React.Ref<MenuToggleElement>) => (
          <MenuToggle
            ref={toggleRef}
            aria-label="More actions"
            variant="plain"
            onClick={() => setOpen((o) => !o)}
          >
            <EllipsisVIcon />
          </MenuToggle>
        )}
      >
        <DropdownList>
          <DropdownItem>Edit configuration</DropdownItem>
          <DropdownItem>View logs</DropdownItem>
          <DropdownItem>Clone</DropdownItem>
          <DropdownItem isDanger>Delete</DropdownItem>
        </DropdownList>
      </Dropdown>
    </div>
  );
}

export default function ActionsExample() {
  return (
    <div style={{ display: "grid", gap: 24 }}>
      <PrimaryAndSecondary />
      <DestructiveAction />
      <PrimaryAndOverflow />
    </div>
  );
}

/**
 * Bulk selection pattern — the toolbar + select-all + per-row checkbox
 * triplet for "select many, act on many" lists.
 *
 * BulkSelect comes from @patternfly/react-component-groups (installed
 * alongside the lib).
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { useId, useState } from "react";
import {
  Button,
  Table,
  Tbody,
  Td,
  Th,
  Thead,
  Toolbar,
  ToolbarContent,
  ToolbarItem,
  Tr,
} from "@golden-passport/ds-patternfly";
import BulkSelect, { BulkSelectValue } from "@patternfly/react-component-groups/dist/dynamic/BulkSelect";

type Workflow = { id: string; name: string; status: string };
const ROWS: Workflow[] = Array.from({ length: 14 }).map((_, i) => ({
  id: `wf-${i + 1}`,
  name: `Workflow ${i + 1}`,
  status: ["Active", "Paused", "Failed"][i % 3] ?? "Active",
}));
const PAGE = 5;

export function FullPattern() {
  const toolbarId = useId();
  const [page, setPage] = useState(1);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const start = (page - 1) * PAGE;
  const pageRows = ROWS.slice(start, start + PAGE);
  const pageSelectedCount = pageRows.filter((r) => selected.has(r.id)).length;
  const pageSelected = pageSelectedCount === pageRows.length;
  const pagePartial = pageSelectedCount > 0 && !pageSelected;

  const onBulk = (v: BulkSelectValue) => {
    setSelected((p) => {
      const next = new Set(p);
      switch (v) {
        case "all":
          ROWS.forEach((r) => next.add(r.id));
          break;
        case "none":
          next.clear();
          break;
        case "page":
          pageRows.forEach((r) => next.add(r.id));
          break;
        case "nonePage":
          pageRows.forEach((r) => next.delete(r.id));
          break;
      }
      return next;
    });
  };

  const toggleRow = (id: string) =>
    setSelected((p) => {
      const next = new Set(p);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });

  return (
    <>
      <Toolbar id={`${toolbarId}-bulk-toolbar`}>
        <ToolbarContent>
          <ToolbarItem>
            <BulkSelect
              isDataPaginated
              canSelectAll
              pageCount={pageRows.length}
              totalCount={ROWS.length}
              selectedCount={selected.size}
              pageSelected={pageSelected}
              pagePartiallySelected={pagePartial}
              onSelect={onBulk}
            />
          </ToolbarItem>
          {selected.size > 0 && (
            <>
              <ToolbarItem variant="separator" />
              <ToolbarItem>
                <Button variant="secondary">Run {selected.size}</Button>
              </ToolbarItem>
              <ToolbarItem>
                <Button variant="danger">Delete {selected.size}</Button>
              </ToolbarItem>
            </>
          )}
          <ToolbarItem align={{ default: "alignEnd" }}>
            <Button variant="link" onClick={() => setPage((p) => (p < 3 ? p + 1 : 1))}>
              Page {page} of 3 →
            </Button>
          </ToolbarItem>
        </ToolbarContent>
      </Toolbar>
      <Table aria-label="Workflows" variant="compact">
        <Thead>
          <Tr>
            <Th screenReaderText="Row select" />
            <Th>Name</Th>
            <Th>Status</Th>
          </Tr>
        </Thead>
        <Tbody>
          {pageRows.map((r, rowIndex) => (
            <Tr key={r.id}>
              <Td
                select={{
                  rowIndex,
                  onSelect: () => toggleRow(r.id),
                  isSelected: selected.has(r.id),
                }}
              />
              <Td dataLabel="Name">{r.name}</Td>
              <Td dataLabel="Status">{r.status}</Td>
            </Tr>
          ))}
        </Tbody>
      </Table>
    </>
  );
}

export default function BulkSelectionExample() {
  return <FullPattern />;
}

/**
 * Card view pattern — a responsive Gallery of Cards as the standard
 * alternative to a Table, paired with a Toolbar for search.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { useId, useState } from "react";
import {
  Card,
  CardBody,
  CardHeader,
  CardTitle,
  Gallery,
  GalleryItem,
  Label,
  SearchInput,
  Toolbar,
  ToolbarContent,
  ToolbarItem,
} from "@golden-passport/ds-patternfly";
import { CubeIcon } from "@patternfly/react-icons";

type Item = { id: string; name: string; desc: string; status: "Active" | "Paused" };
const ITEMS: Item[] = [
  { id: "wf-1", name: "Quarterly review",   desc: "Hourly · 4 steps",        status: "Active" },
  { id: "wf-2", name: "Nightly build",      desc: "On push · 6 steps",       status: "Active" },
  { id: "wf-3", name: "Backup pipeline",    desc: "Daily · 3 steps",         status: "Paused" },
  { id: "wf-4", name: "Audit export",       desc: "Weekly · 2 steps",        status: "Active" },
  { id: "wf-5", name: "Index rebuilder",    desc: "Every 2h · 4 steps",      status: "Active" },
  { id: "wf-6", name: "Notify on incident", desc: "Webhook · 1 step",        status: "Paused" },
];

export function SearchableGallery() {
  const id = useId();
  const [q, setQ] = useState("");
  const filtered = ITEMS.filter((it) =>
    it.name.toLowerCase().includes(q.toLowerCase()),
  );

  return (
    <>
      <Toolbar id={`${id}-cards-toolbar`}>
        <ToolbarContent>
          <ToolbarItem>
            <SearchInput
              placeholder="Filter by name"
              value={q}
              onChange={(_e, v) => setQ(v)}
              onClear={() => setQ("")}
              aria-label="Filter cards"
            />
          </ToolbarItem>
          <ToolbarItem align={{ default: "alignEnd" }}>
            <span style={{ color: "var(--gp-color-text-subtle)" }}>
              {filtered.length} of {ITEMS.length}
            </span>
          </ToolbarItem>
        </ToolbarContent>
      </Toolbar>
      <Gallery hasGutter minWidths={{ default: "260px" }}>
        {filtered.map((it) => (
          <GalleryItem key={it.id}>
            <Card isCompact>
              <CardHeader>
                <CubeIcon />
                <CardTitle>{it.name}</CardTitle>
              </CardHeader>
              <CardBody>
                <p style={{ margin: 0, color: "var(--gp-color-text-subtle)" }}>
                  {it.desc}
                </p>
                <p style={{ margin: "12px 0 0" }}>
                  <Label color={it.status === "Active" ? "green" : "grey"} isCompact>
                    {it.status}
                  </Label>
                </p>
              </CardBody>
            </Card>
          </GalleryItem>
        ))}
      </Gallery>
    </>
  );
}

export default function CardViewExample() {
  return <SearchableGallery />;
}

