  return <SearchFacetsChips />;
}

/**
 * Password generator pattern — read-only TextInput + regenerate / show /
 * copy buttons in an InputGroup. Cryptographically random via
 * crypto.getRandomValues — never Math.random().
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { useId, useState } from "react";
import {
  Button,
  InputGroup,
  InputGroupItem,
  TextInput,
} from "@golden-passport/ds-patternfly";
import { CopyIcon, EyeIcon, EyeSlashIcon, SyncIcon } from "@patternfly/react-icons";

const ALPHA_L = "abcdefghijkmnopqrstuvwxyz"; // no l
const ALPHA_U = "ABCDEFGHJKLMNPQRSTUVWXYZ";  // no I/O
const DIGITS  = "23456789";                  // no 0/1
const SYM     = "!@#$%^&*-_=+";

function generate(len = 16): string {
  const pool = ALPHA_L + ALPHA_U + DIGITS + SYM;
  const out = new Array<string>(len);
  if (typeof crypto !== "undefined" && crypto.getRandomValues) {
    const buf = new Uint32Array(len);
    crypto.getRandomValues(buf);
    for (let i = 0; i < len; i++) out[i] = pool[(buf[i] ?? 0) % pool.length] ?? "x";
  } else {
    for (let i = 0; i < len; i++) out[i] = pool[Math.floor(Math.random() * pool.length)] ?? "x";
  }
  return out.join("");
}

export function GeneratorInputGroup() {
  const id = useId();
  const [pwd, setPwd] = useState(() => generate(16));
  const [show, setShow] = useState(false);
  const [copied, setCopied] = useState(false);

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(pwd);
      setCopied(true);
      setTimeout(() => setCopied(false), 1500);
    } catch {
      /* ignore — clipboard may be blocked in iframes */
    }
  };

  return (
    <div style={{ maxWidth: 480, display: "grid", gap: 8 }}>
      <InputGroup>
        <InputGroupItem isFill>
          <TextInput
            id={`${id}-pwd-gen`}
            aria-label="Generated password"
            type={show ? "text" : "password"}
            value={pwd}
            readOnlyVariant="default"
          />
        </InputGroupItem>
        <InputGroupItem>
          <Button
            variant="control"
            aria-label={show ? "Hide password" : "Show password"}
            onClick={() => setShow((s) => !s)}
          >
            {show ? <EyeSlashIcon /> : <EyeIcon />}
          </Button>
        </InputGroupItem>
        <InputGroupItem>
          <Button
            variant="control"
            aria-label="Generate new password"
            onClick={() => setPwd(generate(16))}
          >
            <SyncIcon />
          </Button>
        </InputGroupItem>
        <InputGroupItem>
          <Button
            variant="control"
            aria-label="Copy password"
            onClick={copy}
          >
            <CopyIcon />
          </Button>
        </InputGroupItem>
      </InputGroup>
      <p
        aria-live="polite"
        style={{ margin: 0, height: 18, color: "var(--gp-color-text-subtle)", fontSize: 13 }}
      >
        {copied ? "Copied to clipboard." : ""}
      </p>
    </div>
  );
}

export default function PasswordGeneratorExample() {
  return <GeneratorInputGroup />;
}

/**
 * Password strength pattern — a live strength meter (Progress) plus a
 * per-rule criteria checklist (HelperText) that update as the user types.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { useId, useMemo, useState } from "react";
import {
  HelperText,
  HelperTextItem,
  Progress,
  ProgressMeasureLocation,
  ProgressSize,
  TextInput,
} from "@golden-passport/ds-patternfly";

type Score = { value: number; label: string; variant: "danger" | "warning" | "success" };

function score(pwd: string): Score {
  let s = 0;
  if (pwd.length >= 8) s++;
  if (pwd.length >= 12) s++;
  if (/[a-z]/.test(pwd) && /[A-Z]/.test(pwd)) s++;
  if (/\d/.test(pwd)) s++;
  if (/[^a-zA-Z0-9]/.test(pwd)) s++;
  // common-word heuristic — toy version
  if (/password|qwerty|12345/i.test(pwd)) s = Math.max(0, s - 2);
  const pct = Math.min(100, (s / 5) * 100);
  if (s <= 1) return { value: pct, label: "Weak",     variant: "danger"  };
  if (s <= 3) return { value: pct, label: "Fair",     variant: "warning" };
  return                 { value: pct, label: "Strong",   variant: "success" };
}

const Criterion = ({ ok, children }: { ok: boolean; children: React.ReactNode }) => (
  <HelperTextItem
    variant={ok ? "success" : "default"}
  >
    {children}
  </HelperTextItem>
);

export function MeterAndCriteria() {
  const id = useId();
  const [pwd, setPwd] = useState("");
  const s = useMemo(() => score(pwd), [pwd]);

  return (
    <div style={{ maxWidth: 480, display: "grid", gap: 8 }}>
      <TextInput
        id={`${id}-pwd-strength`}
        type="password"
        value={pwd}
        onChange={(_e, v) => setPwd(v)}
        aria-label="New password"
        placeholder="Type a password"
        aria-describedby={`${id}-pwd-strength-meter ${id}-pwd-strength-criteria`}
      />
      <div id={`${id}-pwd-strength-meter`}>
        <Progress
          value={s.value}
          title={`Password strength: ${s.label}`}
          variant={s.variant}
          size={ProgressSize.sm}
          measureLocation={ProgressMeasureLocation.outside}
          aria-live="polite"
        />
      </div>
      <HelperText id={`${id}-pwd-strength-criteria`}>
        <Criterion ok={pwd.length >= 8}>At least 8 characters</Criterion>
        <Criterion ok={pwd.length >= 12}>12 or more characters</Criterion>
        <Criterion ok={/[a-z]/.test(pwd) && /[A-Z]/.test(pwd)}>Mixed case (a–z + A–Z)</Criterion>
        <Criterion ok={/\d/.test(pwd)}>A digit</Criterion>
        <Criterion ok={/[^a-zA-Z0-9]/.test(pwd)}>A symbol</Criterion>
      </HelperText>
    </div>
  );
}

export default function PasswordStrengthExample() {
  return <MeterAndCriteria />;
}

